88	        await SeedOfferAsync(db, "P1", "L1", 10m);
89	        await SeedOfferAsync(db, "P2", "L1", 5m);
90	        var service = new OrderService(db);
91	        var created = await service.CreateOrderAsync(new CreateOrderRequestDto(
92	            "Jonas", "Hauptstr. 1", "12345", "Berlin", "DE", "j@example.com",
93	            [new OrderLineRequestDto("P1", "L1", 2), new OrderLineRequestDto("P2", "L1", 3)]));
94	
95	        var result = await service.GetOrderAsync(created.OrderId!.Value);
96	
97	        Assert.NotNull(result);
98	        Assert.Equal("Eingegangen", result!.Status);
99	        Assert.Equal(2, result.Items.Count);
100	        Assert.Contains(result.Items, i => i.SupplierName == "Lieferant L1" && i.UnitPrice == 10m && i.Quantity == 2);
101	        Assert.Contains(result.Items, i => i.SupplierName == "Lieferant L1" && i.UnitPrice == 5m && i.Quantity == 3);
